```ts
function usePaged<T>(load: (c?: string) => Promise<{items: T[]; next?: string}>) {
  const [items, setItems] = useState<T[]>([]);
  const [cursor, setCursor] = useState<string>();
  const more = async () => { const r = await load(cursor); setItems(i => [...i, ...r.items]); setCursor(r.next); };
  return { items, more };
}
```

